      "time": "25 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 3 of the Contract Clause Extractor (part 1) - rolls up per-clause\nrisk ratings into one overall contract risk level.\n\"\"\"\n\n\ndef count_risk_levels(clauses):\n    \"\"\"Pure function - counts red/yellow/green/unclear across all clauses.\"\"\"\n    counts = {\"red\": 0, \"yellow\": 0, \"green\": 0, \"unclear\": 0}\n    for data in clauses.values():\n        risk = data.get(\"risk\", \"unclear\")\n        counts[risk] = counts.get(risk, 0) + 1\n    return counts\n\n\ndef overall_risk(clauses):\n    \"\"\"\n    Returns \"High Risk\", \"Medium Risk\", or \"Low Risk\" based on how many\n    clauses are rated red/yellow.\n\n        overall_risk(clauses)\n\n    Rule: 2+ red -> High Risk. 1 red OR 4+ yellow -> Medium Risk.\n    Otherwise -> Low Risk. Deliberately simple and explainable - a\n    lawyer using this tool can recompute the same rating by hand from\n    the counts alone, which matters more here than a more \"clever\" but\n    opaque scoring formula would.\n    \"\"\"\n    counts = count_risk_levels(clauses)\n\n    if counts[\"red\"] >= 2:\n        return \"High Risk\"\n    if counts[\"red\"] == 1 or counts[\"yellow\"] >= 4:\n        return \"Medium Risk\"\n    return \"Low Risk\"\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the roll-up logic works - no AI\n    # call, no API usage:  python risk.py\n    print(\"Checking 2+ red clauses -> High Risk...\")\n    two_red = {f\"clause{i}\": {\"risk\": \"red\"} for i in range(2)}\n    assert overall_risk(two_red) == \"High Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking exactly 1 red clause -> Medium Risk...\")\n    one_red = {\"clause1\": {\"risk\": \"red\"}, \"clause2\": {\"risk\": \"green\"}}\n    assert overall_risk(one_red) == \"Medium Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking 4+ yellow (no red) -> Medium Risk...\")\n    four_yellow = {f\"clause{i}\": {\"risk\": \"yellow\"} for i in range(4)}\n    assert overall_risk(four_yellow) == \"Medium Risk\"\n    print(\"  OK\")\n\n    print(\"\\nChecking mostly green, a couple yellow -> Low Risk...\")\n    mostly_green = {\"c1\": {\"risk\": \"green\"}, \"c2\": {\"risk\": \"green\"}, \"c3\": {\"risk\": \"yellow\"}}\n    assert overall_risk(mostly_green) == \"Low Risk\"\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python risk.py`. You should see 2+ red clauses correctly producing High Risk, exactly 1 red producing Medium Risk, 4+ yellow with no red also producing Medium Risk, and a mostly-green set producing Low Risk - ending with `All checks passed.`",
          "instruction": "Create `risk.py` with this code:"
        },
        {
          "prompt": "\"\"\"\nStep 3 of the Contract Clause Extractor (part 2) - flags clauses that\ndeviate from your organization's standard language.\n\"\"\"\n\nSTANDARD_CLAUSES = {\n    \"Limitation of Liability\": \"Liability shall not exceed fees paid in the preceding 12 months.\",\n    \"Governing Law\": \"This agreement shall be governed by the laws of Delaware.\",\n}\n\n\ndef flag_deviations(clauses, standard_clauses=STANDARD_CLAUSES):\n    \"\"\"\n    Compares the first 3 words of each standard clause against the\n    first 3 words of the actual extracted clause, and returns a dict of\n    deviations with both the standard and actual text for any mismatch.\n\n        flag_deviations(clauses)\n\n    The word-prefix check is a starting heuristic, not a semantic\n    comparison - it catches wording that opens noticeably differently,\n    but two clauses that start the same way and diverge in the middle\n    would slip past it. Production use should ask the AI to assess\n    semantic similarity instead (see this build's goFurther).\n    \"\"\"\n    deviations = {}\n\n    for clause_type, standard_text in standard_clauses.items():\n        actual = clauses.get(clause_type, {}).get(\"exact_text\", \"\")\n        if actual.strip().lower() == \"not found\":\n            deviations[clause_type] = {\"standard\": standard_text, \"actual\": \"Not found in contract\"}\n            continue\n\n        standard_prefix = \" \".join(standard_text.split()[:3]).lower()\n        actual_prefix = \" \".join(actual.split()[:3]).lower()\n\n        if standard_prefix != actual_prefix:\n            deviations[clause_type] = {\"standard\": standard_text, \"actual\": actual}\n\n    return deviations\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the deviation logic works - no\n    # AI call, no API usage:  python standard_library.py\n    print(\"Checking a clause matching the standard's opening words...\")\n    matching = {\"Governing Law\": {\"exact_text\": \"This agreement shall be governed by the laws of Texas, not Delaware.\"}}\n    result = flag_deviations(matching)\n    assert \"Governing Law\" not in result\n    print(\"  OK - same opening 3 words, not flagged (even though the state differs later in the sentence -\")\n    print(\"  this IS the heuristic's known limitation, and exactly why the goFurther suggests a semantic check)\")\n\n    print(\"\\nChecking a clause with a genuinely different opening...\")\n    different = {\"Limitation of Liability\": {\"exact_text\": \"In no event shall either party be liable for any damages.\"}}\n    result = flag_deviations(different)\n    assert \"Limitation of Liability\" in result\n    assert result[\"Limitation of Liability\"][\"actual\"].startswith(\"In no event\")\n    print(\"  OK -\", result[\"Limitation of Liability\"])\n\n    print(\"\\nChecking a clause the AI couldn't find at all is flagged as a deviation...\")\n    missing = {\"Governing Law\": {\"exact_text\": \"Not found\"}}\n    result = flag_deviations(missing)\n    assert result[\"Governing Law\"][\"actual\"] == \"Not found in contract\"\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python standard_library.py`. You should see a clause matching the standard's opening words correctly NOT flagged, a genuinely different opening correctly flagged with both texts shown, and a clause the AI couldn't find at all correctly flagged as a deviation - ending with `All checks passed.`",
          "instruction": "Create `standard_library.py` with this code, then edit STANDARD_CLAUSES to match your own organization's preferred language:"
        }
